import {colourHSL,colourHex,harmonyColours,harmonies,colourWheel,contrastResult} from './colour-tools.mjs';
import {ramp,contrast,rampExport} from './core.mjs';
export function rampTool({change,status}){const $=id=>document.getElementById(id);let color='#709f48',name='brand',rows=[],harmony='complementary',foreground=color,background='#ffffff',followBrand=true;
  function tools(){if(!$('ramp-wheel'))return;const hsl=colourHSL(color);$('ramp-wheel').innerHTML=colourWheel(color,harmony);$('ramp-harmony').value=harmony;for(const [key,value] of Object.entries({hue:hsl.h,saturation:hsl.s,lightness:hsl.l})){$('ramp-'+key).value=Math.round(value);$('ramp-'+key+'-value').textContent=(key==='hue'?Math.floor(value):Math.round(value))+(key==='hue'?'°':'%')}$('ramp-hue').disabled=hsl.s===0||hsl.l===0||hsl.l===100;$('ramp-saturation').disabled=hsl.l===0||hsl.l===100;$('ramp-palette').replaceChildren();for(const hex of harmonyColours(color,harmony)){const button=document.createElement('button');button.type='button';button.className='studio-palette-swatch';button.style.background=hex;button.style.color=contrast(hex,'#000000')>contrast(hex,'#ffffff')?'#000000':'#ffffff';button.textContent=hex;button.setAttribute('aria-label','Use '+hex+' as base colour');button.onclick=()=>{color=hex;$('ramp-colour').value=color;$('ramp-hex').value=color;$('ramp-hex').setCustomValidity('');draw()};$('ramp-palette').append(button)}$('ramp-foreground').value=foreground;$('ramp-background').value=background;const result=contrastResult(foreground,background);$('ramp-check-preview').style.color=foreground;$('ramp-check-preview').style.background=background;$('ramp-check-result').textContent=`${result.ratio.toFixed(2)}:1 · Normal text AA: ${result.normalAA?'Pass':'Fail'} · Large text AA: ${result.largeAA?'Pass':'Fail'} · Normal text AAA: ${result.normalAAA?'Pass':'Fail'}`}
  function draw(){if(followBrand)foreground=color;tools();rows=ramp(color);$('ramp-preview').replaceChildren();$('ramp-contrast').replaceChildren();for(const r of rows){const block=document.createElement('div');block.className='studio-ramp-swatch';block.style.background=r.color;block.style.color=contrast(r.color,'#000000')>=contrast(r.color,'#ffffff')?'#000000':'#ffffff';const n=document.createElement('span');n.textContent=r.level;const hex=document.createElement('code');hex.textContent=r.color;const label=document.createElement('small');label.textContent=r.white>=4.5?'White AA':'Black AA';block.append(n,hex,label);$('ramp-preview').append(block);const row=document.createElement('tr');for(const text of [r.level,r.color,`${r.white.toFixed(2)}:1 ${r.white>=4.5?'· AA':'· fails AA'}`,`${r.black.toFixed(2)}:1 ${r.black>=4.5?'· AA':'· fails AA'}`]){const cell=document.createElement('td');cell.textContent=text;row.append(cell)}$('ramp-contrast').append(row)}change()}
  $('ramp-colour').oninput=e=>{color=e.target.value;$('ramp-hex').value=color;$('ramp-hex').setCustomValidity('');draw()};$('ramp-hex').oninput=e=>{if(!/^#[a-f0-9]{6}$/i.test(e.target.value)){e.target.setCustomValidity('Use a six-digit hex colour, such as #709f48.');return}e.target.setCustomValidity('');color=e.target.value;$('ramp-colour').value=color;draw()};$('ramp-name').oninput=e=>{const valid=/^[a-z][a-z0-9-]{0,29}$/.test(e.target.value);e.target.setCustomValidity(valid?'':'Use lowercase letters, numbers and hyphens, starting with a letter.');if(valid){name=e.target.value;change()}};
  if($('ramp-harmony')){$('ramp-explore').onclick=()=>{$('ramp-lab-title').scrollIntoView({block:'start'});$('ramp-lab-title').focus({preventScroll:true})};$('ramp-view-scale').onclick=()=>$('ramp-preview').scrollIntoView({block:'start'});$('ramp-harmony').onchange=e=>{harmony=Object.hasOwn(harmonies,e.target.value)?e.target.value:'complementary';draw()};for(const key of ['hue','saturation','lightness'])$('ramp-'+key).oninput=e=>{const hsl=colourHSL(color);hsl[{hue:'h',saturation:'s',lightness:'l'}[key]]=Number(e.target.value);color=colourHex(hsl.h,hsl.s,hsl.l);$('ramp-colour').value=color;$('ramp-hex').value=color;$('ramp-hex').setCustomValidity('');draw()};const pick=e=>{const rect=$('ramp-wheel').getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width-.5,y=(e.clientY-rect.top)/rect.height-.5,hsl=colourHSL(color);color=colourHex(Math.atan2(y,x)*180/Math.PI+90,hsl.s||70,hsl.l===0||hsl.l===100?50:hsl.l);$('ramp-colour').value=color;$('ramp-hex').value=color;$('ramp-hex').setCustomValidity('');draw()};let dragging=false;$('ramp-wheel').onpointerdown=e=>{dragging=true;$('ramp-wheel').setPointerCapture(e.pointerId);pick(e)};$('ramp-wheel').onpointermove=e=>{if(dragging)pick(e)};$('ramp-wheel').onpointerup=$('ramp-wheel').onpointercancel=()=>dragging=false;for(const key of ['foreground','background'])$('ramp-'+key).oninput=e=>{if(key==='foreground'){foreground=e.target.value;followBrand=false;}else background=e.target.value;draw()};$('ramp-swap').onclick=()=>{followBrand=false;[foreground,background]=[background,foreground];draw()};$('ramp-use-base').onclick=()=>{followBrand=true;foreground=color;draw()}}
  draw();return {get:()=>({color,name,harmony,foreground,background,followBrand}),set:v=>{followBrand=v?.followBrand===true||!(/^#[a-f0-9]{6}$/i.test(v?.foreground)&&typeof v?.foreground==='string');harmony=Object.hasOwn(harmonies,v?.harmony)?v.harmony:harmony;if(typeof v?.foreground==='string'&&/^#[a-f0-9]{6}$/i.test(v.foreground))foreground=v.foreground;if(typeof v?.background==='string'&&/^#[a-f0-9]{6}$/i.test(v.background))background=v.background;if(typeof v?.color==='string'&&/^#[a-f0-9]{6}$/i.test(v.color))color=v.color;if(typeof v?.name==='string'&&/^[a-z][a-z0-9-]{0,29}$/.test(v.name))name=v.name;$('ramp-colour').value=color;$('ramp-hex').value=color;$('ramp-hex').setCustomValidity('');$('ramp-name').value=name;$('ramp-name').setCustomValidity('');draw()},export:format=>{if(!$('ramp-name').reportValidity()||!$('ramp-hex').reportValidity())throw Error('Fix the colour or token name before exporting.');if(format==='harmony-json')return JSON.stringify({base:color,harmony,colours:harmonyColours(color,harmony)},null,2);if(format==='harmony-css')return ':root {\n'+harmonyColours(color,harmony).map((c,i)=>'  --'+name+'-harmony-'+(i+1)+': '+c+';').join('\n')+'\n}';return rampExport(rows,name,format)}};
}
